   !$acc declare create(boys_table)



contains

   !
   ! Push the table to the device.  `declare create` allocates device storage
   ! but does NOT carry the host initialiser across -- a device copy full of
   ! garbage is exactly the silent-wrong-answer failure the whole project is
   ! trying to avoid, so the transfer is explicit and must be called once
   ! before any kernel.
   !
   subroutine boys_init()
      !$acc update device(boys_table)
   end subroutine boys_init

   ! boys_eval lives in src/inc/trc_boys_eval.inc, included here for the
   ! host and in every kernel module that calls it on the device -- see the
   ! note at the top of that file.
#include "inc/trc_boys_eval.inc"

end module trc_boys
